const calculator = new Calculator();
// Act
const result = calculator.add(2, 3);
// Assert
expect(result).toBe(5);

describe('Calculator', () => {
  it('should add two numbers', () => {
    // Given
    const calc = new Calculator();
    // When
    const sum = calc.add(2, 3);
    // Then
    expect(sum).toBe(5);
  });
});

